import {mapReadingView,startMapReading,keepMapLine,keepMapGap,keepMapText,supportMapReading,keepMapEdition,reviseMapEdition} from './map-reading-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels=['Copy','Missing words','Retellings',"Editor’s note"];
const flags={example:'Example supplied',comparison:'Side-by-side comparison',narration:'Narration requested',together:'Working together reported'};
let visit=null,removeGuards=()=>{},pendingNavigation=()=>false;
export function resetMapReading(){removeGuards();removeGuards=()=>{};pendingNavigation=()=>false;visit=null;}
export const guardMapReadingNavigation=()=>pendingNavigation();
function session(notebook,owner){if(!visit||visit.notebook!==notebook||visit.owner!==owner){resetMapReading();visit={notebook,owner,id:null,step:0,line:0,gap:0,source:'original',drawer:false,tools:false,side:false,example:null,confirm:false,page:0,notice:'',pending:new Map()};}return visit;}
const key=(s,k)=>`${s.id}/${k}`;
function saved(v,k){if(k.startsWith('line/'))return v.writing?.lines.find(x=>x.lineId===k.slice(5))?.text??'';if(k.startsWith('gap/')){const slash=k.lastIndexOf('/'),id=k.slice(4,slash),field=k.slice(slash+1);return v.writing?.gaps.find(x=>x.gapId===id)?.[field]??'';}return v.writing?.[k]?.text??'';}
const value=(s,v,k)=>s.pending.has(key(s,k))?s.pending.get(key(s,k)):saved(v,k);
const dirty=(s,v)=>[...s.pending].filter(([k,t])=>k.startsWith(`${s.id}/`)&&t!==saved(v,k.slice(s.id.length+1)));
const btn=(action,title,attrs='')=>`<button type="button" data-map-action="${action}" ${attrs}>${esc(title)}</button>`;
const para=(text,read=true)=>text?`<p${read?' data-map-read':''}>${esc(text)}</p>`:'';
const support=s=>`<ul class="map-support">${Object.entries(flags).map(([k,label])=>`<li>${label}: ${s?.[k]===true?'Yes':'No'}</li>`).join('')}</ul>`;
const literal=x=>para(x?.length?x:'Not written',false);
function textarea(s,v,k,label){return `<label class="map-field">${esc(label)}<textarea data-map-field="${esc(k)}" rows="4" maxlength="4000" autocorrect="off" autocapitalize="off" spellcheck="false">${esc(value(s,v,k))}</textarea></label>`;}
function source(v,s){const names={original:'Original source copy',short:'Short retelling',longer:'Longer retelling'};return `<details class="map-source"${s.drawer?' open':''}><summary>Read the whole source and retellings</summary><div class="map-actions" role="group" aria-label="Choose a source version">${Object.entries(names).map(([k,title])=>btn('source',title,`data-map-source="${k}" aria-pressed="${s.source===k}"`)).join('')}</div><h3 id="map-source-title" tabindex="-1" data-map-read>${names[s.source]}</h3>${para(v.source[s.source])}${para(v.source.limitation)}<a href="#almanac/keepers">Picture context on the Keeper’s Page</a></details>`;}
function preview(v){const w=v.writing;return `<article class="map-edition"><h3 data-map-read>Source copy</h3>${para(v.source.original,false)}<h3>Your sentence copies</h3>${v.source.lines.map(l=>`<section><h4>${esc(l.text)}</h4>${literal(w.lines.find(x=>x.lineId===l.id)?.text)}${w.lines.some(x=>x.lineId===l.id)?support(w.lines.find(x=>x.lineId===l.id).supportBefore):''}</section>`).join('')}<h3>Margin hypotheses · not recovered writing</h3>${v.source.gaps.map((g,i)=>{const a=w.gaps.find(x=>x.gapId===g.id);return `<section><h4>Gap ${i+1}</h4>${para(v.source.lines.find(l=>l.id===g.lineId).text,false)}${para(a?.proposal?`Possible reading: [${a.proposal}?]`:'No reading proposed',false)}${literal(a?.reason)}${a?support(a.supportBefore):''}</section>`;}).join('')}<h3>Your retelling comparison</h3>${literal(w.comparison?.text)}${w.comparison?support(w.comparison.supportBefore):''}<h3>Your editor’s note</h3>${literal(w.note?.text)}${w.note?support(w.note.supportBefore):''}<details><summary>Support for this edition</summary>${support(w.support)}</details></article>`;}
function chooser(s,v){const pageCount=Math.max(1,Math.ceil(v.packets.length/6));s.page=Math.min(s.page,pageCount-1);return `<h2 id="map-heading" tabindex="-1">An editor’s workbench</h2><p>Keep the page’s words apart from your ideas. Your writing is not automatically marked. New editions revisit this same authored page. Unsent writing lasts for this visit; reloading discards only words you have not kept.</p>${v.status==='unsupported'?'<p>This earlier saved format is retained. Other places stay open.</p>':v.canStart?btn('start','Start an edition',v.canCreate?'class="primary"':'disabled'):'<p>Open the first Keeper’s Page, or choose an arrival with its story context, before starting a new edition. This does not record earlier lessons as completed.</p><div class="map-actions"><a href="#almanac/keepers">Visit the Keeper’s Page</a><a href="#arrive">Choose an arrival</a></div>'}${!v.canCreate&&v.status!=='unsupported'?'<p>A new edition cannot be started here. Earlier writing stays open and exportable.</p>':''}<h3>Earlier editions</h3>${v.packets.length?v.packets.slice(s.page*6,s.page*6+6).map(p=>p.readable?`<div class="map-saved-row">${btn('open',`${p.source.title} · ${p.id} · ${p.kept?'Kept edition':'In progress'}`,`data-map-id="${p.id}"`)}</div>`:'<p>Earlier edition retained · its original stays in your notes.</p>').join(''):'<p>No editions started.</p>'}<div class="map-actions">${btn('pages-prev','Previous editions',s.page===0?'disabled':'')}${btn('pages-next','Next editions',s.page===pageCount-1?'disabled':'')}</div>`;}
function editor(s,v){
 if(!v.readable)return `<h2 id="map-heading" tabindex="-1">Earlier edition retained</h2><p>Its original stays in your notes. Other editions remain open.</p>${btn('choose','Choose an edition')}`;
 if(v.kept||s.confirm)return `<h2 id="map-heading" tabindex="-1">${v.kept?'Kept edition':'Check this saved edition'}</h2>${para(v.kept?'Your literal writing is kept, not marked or scored.':v.helper?.keep||'Only the saved writing below will be kept. Unsent changes are not included. You may keep a partial edition.')}${dirty(s,v).length?'<p class="map-warning">There are unsent words. They are not included below. Return to your writing to keep them first.</p>':''}${preview(v)}<div class="map-actions">${v.kept?btn('revise','Revise as a new edition',v.canRevise?'':'disabled')+btn('choose','Choose an edition'):btn('confirm','Keep this edition','class="primary"')+btn('cancel-confirm','Return to my writing')}</div>`;
 const t=v.helper;s.line=Math.min(s.line,v.source.lines.length-1);s.gap=Math.min(s.gap,v.source.gaps.length-1);
 if(s.example!==null)return `<h2 id="map-heading" tabindex="-1" data-map-read>${esc(t?.exampleTitle||'Earlier example retained')}</h2><p class="map-badge" data-map-read>Example, not your map</p><h3 data-map-read>${['Source copy','Supplied example copy','Margin hypothesis','Editor’s note'][s.example]}</h3>${t?para(t.example[s.example]):'<p>This earlier helper is retained; your writing stays open.</p>'}<div class="map-actions">${btn('example-prev','Previous example part',s.example===0?'disabled':'')}${btn('example-next','Next example part',s.example===3?'disabled':'')}${btn('close-example','Return to my writing')}${hearButton('','Hear this example')}</div>`;
 let body='';
 if(s.step===0){const l=v.source.lines[s.line],k=`line/${l.id}`;body=`${para(t?.copy)}<div class="map-strips" role="group" aria-label="Choose a source sentence">${v.source.lines.map((l,i)=>btn('line',`Sentence ${i+1}`,`data-map-index="${i}" aria-pressed="${s.line===i}"`)).join('')}</div><div class="map-source-strip"><h3 data-map-read>Source copy</h3>${para(l.text)}</div>${textarea(s,v,k,'Your copy')}<div class="map-actions">${btn('save-line','Keep these words','class="primary"')}${btn('side','Read side by side')}${btn('line-prev','Previous sentence',s.line===0?'disabled':'')}${btn('line-next','Next sentence',s.line===v.source.lines.length-1?'disabled':'')}</div>${s.side?`<section class="map-side"><h3 data-map-read>Source copy</h3>${para(l.text)}<h3>Your copy · not automatically checked</h3><p data-map-side-copy>${esc(value(s,v,k)||'Not written')}</p></section>`:''}<details><summary>About careful copying</summary>${para(t?.copySupport)}</details>`;}
 if(s.step===1){const g=v.source.gaps[s.gap],line=v.source.lines.find(l=>l.id===g.lineId),proposal=value(s,v,`gap/${g.id}/proposal`);body=`${para(t?.gaps)}<div class="map-actions" role="group" aria-label="Choose a gap">${v.source.gaps.map((g,i)=>btn('gap',`Gap ${i+1}`,`data-map-index="${i}" aria-pressed="${s.gap===i}"`)).join('')}</div><div class="map-source-strip"><h3 data-map-read>Source copy · unchanged</h3>${para(line.text)}</div>${para(s.gap===0?t?.gap1:s.gap===1?t?.gap2:'')}${textarea(s,v,`gap/${g.id}/proposal`,'Possible reading')}${textarea(s,v,`gap/${g.id}/reason`,'Why might it fit? What is still unknown?')}<aside class="map-margin"><h3>Margin hypothesis</h3><p data-map-hypothesis>${esc(proposal?`Possible reading: [${proposal}?]`:'No reading proposed')}</p><p>A hypothesis, not recovered writing.</p></aside>${btn('save-gap','Keep this margin note','class="primary"')}<details><summary>What can the gap tell us?</summary>${para(t?.gapSupport)}${s.gap===1?para(t?.gap2Support):''}</details>`;}
 if(s.step===2)body=`${para(t?.retellings)}<p>Open the source drawer to compare all three frozen versions.</p>${textarea(s,v,'comparison','What was kept, left out or added? Where does an added detail come from?')}${btn('save-comparison','Keep this comparison','class="primary"')}<details><summary>Picture, words and present-day context</summary>${para(t?.retellingSupport)}${para(t?.further)}</details>`;
 if(s.step===3)body=`${para(t?.note)}${textarea(s,v,'note','Your editor’s note')}${btn('save-note','Keep this note','class="primary"')}<details><summary>What can we establish?</summary>${para(t?.noteSupport)}</details><div class="map-actions">${btn('preview','Review and keep this edition')}</div><p>You can keep a partial edition. Only explicitly kept writing will be included.</p>`;
 return `<nav class="map-steps" aria-label="Editor’s workbench steps">${labels.map((l,i)=>btn('step',`${i+1}. ${l}`,`data-map-index="${i}" aria-current="${i===s.step?'step':'false'}"`)).join('')}</nav><div class="map-workspace"><section class="map-writing"><h2 id="map-heading" tabindex="-1">${labels[s.step]}</h2>${body}</section>${source(v,s)}</div><details class="map-tools"${s.tools?' open':''}><summary>Workbench tools</summary><div class="map-actions">${btn('example','Show an example',t?'':'disabled')}${btn('together',v.writing.support.together?'Working together reported':'Working together')}${hearButton('','Hear this turn')}${btn('choose','Choose an edition')}</div></details>${!t?'<p>This earlier helper is retained; the saved source and writing remain open.</p>':''}<p class="map-unsent" data-map-unsent>${dirty(s,v).length?'These words are not yet kept.':'Only kept writing is included in downloads.'}</p>`;
}
export function mapReadingPage(notebook,owner){const s=session(notebook,owner),v=mapReadingView(notebook,s.id);return `<section class="panel map-reading" data-map-root><header class="map-header"><div><h1>Reading the old map</h1><p class="map-badge">${s.id?'Fictional page · typeset practice copy':'Copy, question, leave a note'}</p></div><nav aria-label="Workbench exits"><a href="#workshop">Workshop</a><a href="#notes">Grown-up notes</a></nav></header><p id="map-status" role="status" aria-live="polite" tabindex="-1"${s.notice?'':' class="sr-only"'}>${esc(s.notice)}</p>${s.id?editor(s,v):chooser(s,v)}${v.source?`<details class="map-notice"><summary>About this source copy</summary>${para(v.source.notice,false)}</details>`:''}</section>`;}
export function bindMapReading(notebook,ctx){
 removeGuards();removeGuards=()=>{};pendingNavigation=()=>false;
 const root=document.querySelector('[data-map-root]');if(!root)return;
 const owner=ctx.explorerId(),s=session(notebook,owner),id=s.id,step=s.step,line=s.line,gap=s.gap,example=s.example,confirm=s.confirm,route='#workshop/old-map',options={canExport:ctx.canExport};
 const live=()=>root.isConnected&&document.querySelector('[data-map-root]')===root&&visit===s&&s.id===id&&s.step===step&&s.line===line&&s.gap===gap&&s.example===example&&s.confirm===confirm&&location.hash===route&&ctx.notebook()===notebook&&ctx.explorerId()===owner&&ctx.isActive?.()!==false;
 const view=()=>mapReadingView(notebook,s.id),stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();};
 const focus=selector=>{const el=document.querySelector(selector);if(el){el.focus({preventScroll:true});const box=el.getBoundingClientRect();if(box.top<0||box.bottom>innerHeight)el.scrollIntoView({block:'nearest'});}};
 const refresh=(selector='#map-heading')=>{ctx.render();focus(selector);};
 const say=(message,take=true)=>{s.notice=message;const el=root.querySelector('#map-status');if(el){el.textContent=message;el.classList.remove('sr-only');if(take)el.focus();}};
 const mutate=(fn,{message='Writing kept. It has not been marked.',render=true,after=null}={})=>{
  if(!live())return false;const r=fn();if(!r?.ok){say(r?.error||'This change could not be kept. Your earlier writing is unchanged.');return false;}
  let status=null;if(r.changed)status=ctx.save?.();if(after)after(r);
  const failed=status?.ok===false;
  if(r.changed)s.notice=failed?'This writing is in this session, but it could not be saved on this device. Download your notes.':status?.enabled===false?'Saving is off. This writing lasts for this session. Download your notes to keep a copy.':message;
  if(render&&(r.changed||after))refresh('#map-status');else if(r.changed)say(s.notice,false);
  return !failed;
 };
 const local=(fn,selector='#map-heading')=>{if(!live())return;stop();fn();refresh(selector);};
 const submitted=(field,result)=>{if(result?.ok)s.pending.delete(key(s,field));return result;};
 const saveField=(field)=>{
  const v=view();if(field.startsWith('line/'))return submitted(field,keepMapLine(notebook,id,field.slice(5),value(s,v,field),options));
  if(field.startsWith('gap/')){const gid=field.slice(4,field.lastIndexOf('/')),p=`gap/${gid}/proposal`,r=`gap/${gid}/reason`,result=keepMapGap(notebook,id,gid,value(s,v,p),value(s,v,r),options);if(result.ok){s.pending.delete(key(s,p));s.pending.delete(key(s,r));}return result;}
  return submitted(field,keepMapText(notebook,id,field,value(s,v,field),options));
 };
 const saveDirty=()=>{for(const [k] of dirty(s,view()))if(!mutate(()=>saveField(k.slice(id.length+1)),{render:false}))return false;return true;};
 let allowDeparture=false,dialog=null;
 const askLeave=action=>{
  if(!live())return;if(!dirty(s,view()).length){action();return;}if(dialog?.isConnected)return;
  dialog=document.createElement('dialog');dialog.className='map-leave';dialog.innerHTML='<h2 tabindex="-1">These words are not yet kept</h2><p>Keep your writing before leaving, leave without keeping it, or stay here.</p><div class="map-actions"><button type="button" data-map-leave="keep">Keep and continue</button><button type="button" data-map-leave="leave">Leave without keeping</button><button type="button" data-map-leave="stay">Stay</button></div>';
  document.body.append(dialog);dialog.showModal();dialog.querySelector('h2').focus();
  const close=()=>{dialog?.close();dialog?.remove();dialog=null;};
  dialog.querySelectorAll('[data-map-leave]').forEach(b=>b.onclick=()=>{if(!live())return close();const choice=b.dataset.mapLeave;if(choice==='stay'){close();focus('#map-heading');return;}if(choice==='keep'&&!saveDirty()){close();focus('#map-status');return;}if(choice==='leave')for(const [k] of dirty(s,view()))s.pending.delete(k);close();allowDeparture=true;action();allowDeparture=false;});
  dialog.addEventListener('cancel',e=>{e.preventDefault();close();focus('#map-heading');});
 };
 const open=next=>{s.id=next;s.step=0;s.line=0;s.gap=0;s.example=null;s.confirm=false;s.side=false;s.source='original';s.notice='';};
 const all=(action,fn)=>root.querySelectorAll(`[data-map-action="${action}"]`).forEach(b=>b.addEventListener('click',()=>{if(live()&&!b.disabled)fn(b);}));
 all('start',()=>askLeave(()=>mutate(()=>startMapReading(notebook,options),{message:'Edition started. Your source copy is frozen.',after:r=>open(r.id)})));
 all('open',b=>askLeave(()=>local(()=>open(b.dataset.mapId))));
 all('choose',()=>askLeave(()=>local(()=>{s.id=null;s.notice='';})));
 all('pages-prev',()=>local(()=>s.page--));all('pages-next',()=>local(()=>s.page++));
 all('step',b=>local(()=>{s.step=Number(b.dataset.mapIndex);s.side=false;}));
 all('line',b=>local(()=>{s.line=Number(b.dataset.mapIndex);s.side=false;}));
 all('line-prev',()=>local(()=>{s.line--;s.side=false;}));all('line-next',()=>local(()=>{s.line++;s.side=false;}));
 all('gap',b=>local(()=>s.gap=Number(b.dataset.mapIndex)));
 all('save-line',()=>mutate(()=>saveField(`line/${view().source.lines[line].id}`)));
 all('save-gap',()=>mutate(()=>saveField(`gap/${view().source.gaps[gap].id}/proposal`)));
 all('save-comparison',()=>mutate(()=>saveField('comparison')));all('save-note',()=>mutate(()=>saveField('note')));
 all('side',()=>mutate(()=>supportMapReading(notebook,id,'comparison',options),{message:'Side-by-side comparison supplied.',after:()=>s.side=true}));
 all('source',b=>local(()=>{s.source=b.dataset.mapSource;s.drawer=true;},'#map-source-title'));
 root.querySelector('.map-tools')?.addEventListener('toggle',e=>{if(live())s.tools=e.currentTarget.open;});
 root.querySelector('.map-source')?.addEventListener('toggle',e=>{if(live())s.drawer=e.currentTarget.open;});
 all('example',()=>mutate(()=>supportMapReading(notebook,id,'example',options),{message:'Example supplied.',after:()=>{s.example=0;s.tools=true;}}));
 all('example-prev',()=>local(()=>s.example--));all('example-next',()=>local(()=>s.example++));
 all('close-example',()=>local(()=>s.example=null,'[data-map-action="example"]'));
 all('together',()=>mutate(()=>supportMapReading(notebook,id,'together',options),{message:'Working together reported.'}));
 all('preview',()=>local(()=>s.confirm=true));all('cancel-confirm',()=>local(()=>s.confirm=false));
 all('confirm',()=>mutate(()=>keepMapEdition(notebook,id,options),{message:'Edition kept. It records your writing, not a passed lesson.',after:()=>{s.confirm=false;for(const [k] of s.pending)if(k.startsWith(`${id}/`))s.pending.delete(k);}}));
 all('revise',()=>mutate(()=>reviseMapEdition(notebook,id,options),{message:'New edition started from this saved source. Earlier writing is preserved; this is a revisit.',after:r=>open(r.id)}));
 root.querySelectorAll('[data-map-field]').forEach(input=>input.addEventListener('input',()=>{if(!live())return;s.pending.set(key(s,input.dataset.mapField),input.value);const n=root.querySelector('[data-map-unsent]');if(n)n.textContent=dirty(s,view()).length?'These words are not yet kept.':'Only kept writing is included in downloads.';const proposal=root.querySelector('[data-map-hypothesis]');if(proposal){const g=view().source.gaps[gap],p=value(s,view(),`gap/${g.id}/proposal`);proposal.textContent=p?`Possible reading: [${p}?]`:'No reading proposed';}const side=root.querySelector('[data-map-side-copy]');if(side)side.textContent=value(s,view(),`line/${view().source.lines[line].id}`)||'Not written';}));
 root.addEventListener('click',e=>{const b=e.target.closest?.('[data-speak]');if(!b||!root.contains(b))return;if(!live()||!mutate(()=>supportMapReading(notebook,id,'narration',options),{render:false,message:'Narration requested.'})){e.preventDefault();e.stopImmediatePropagation();return;}b.dataset.speak=[...root.querySelectorAll('[data-map-read]')].filter(x=>x.getClientRects().length&&getComputedStyle(x).visibility!=='hidden').map(x=>x.innerText).join(' ').replaceAll('[smudged word]','a smudged word');},{capture:true});
 const clickGuard=e=>{if(allowDeparture||!live()||!dirty(s,view()).length)return;const target=e.target.closest?.('a,button,input,select');if(!target||root.contains(target)&&!target.matches('a')||target.closest('.map-leave'))return;e.preventDefault();e.stopImmediatePropagation();askLeave(()=>target.click());};
 document.addEventListener('click',clickGuard,true);
 pendingNavigation=()=>{if(!root.isConnected||visit!==s||ctx.explorerId()!==owner||!dirty(s,view()).length)return false;const next=location.hash;if(next===route)return false;history.replaceState(null,'',route);askLeave(()=>{location.hash=next;});return true;};
 removeGuards=()=>{document.removeEventListener('click',clickGuard,true);dialog?.close();dialog?.remove();pendingNavigation=()=>false;};
}
export function mapReadingNotes(state){
 if(!state||typeof state!=='object'||!Object.hasOwn(state,'mapReading'))return '';
 let body='';try{const v=mapReadingView(state);body=v.packets.map(p=>p.readable?`<details><summary>${esc(p.source.title)} · ${esc(p.id)} · ${p.kept?'Kept':'In progress'}</summary>${para(p.source.notice,false)}${preview(p)}</details>`:'<p>Earlier edition retained · its original stays in your notes.</p>').join('');if(v.status==='unsupported')body='<p>This earlier format is retained; other writing stays open.</p>';}catch{body='<p>Earlier editions retained.</p>';}
 let raw;try{raw=JSON.stringify(state.mapReading,null,2);}catch{raw='Earlier raw value retained; this value cannot be printed here.';}
 return `<section class="panel map-notes"><h2>Reading the old map</h2><p>Original responses, not an automatic grade or mastery assessment. Downloads include explicitly kept writing, not unsent visit text.</p>${body}<details><summary>Exact saved editions</summary><pre>${esc(raw)}</pre></details></section>`;
}
